"""LocalExecutor: a subprocess on the host. Dev/test only — NOT isolated."""

import asyncio
import os
import re
import subprocess
import sys

from agent_workbench.execution.base import BaseExecutor, RawRun, decode_output
from agent_workbench.storage.workspace import RunWorkspace

# Do not pass the server's secrets to code generated by the LLM
_SECRET_ENV = re.compile(r"(KEY|TOKEN|SECRET|PASSWORD)", re.IGNORECASE)


class LocalExecutor(BaseExecutor):
    """
    Runs the code in a subprocess on the machine that runs the server.
    For dev/test only. NOT safe: the code has the same permissions as the user running the server.
    """

    name = "local"

    def __init__(self, timeout: int = 30, runs_dir=None, python: str | None = None):
        super().__init__(timeout=timeout, runs_dir=runs_dir)
        self.python = python or sys.executable
        self._procs: dict[str, subprocess.Popen] = {}

    def prepare_code(self, code: str, workspace: RunWorkspace) -> str:
        # The prompt tells the model to save files to /workspace/output → map that to the run's output/
        return code.replace("/workspace/output", workspace.output_dir.resolve().as_posix())

    async def _run(self, workspace, code_path, language, timeout, progress=None) -> RawRun:
        env = {k: v for k, v in os.environ.items() if not _SECRET_ENV.search(k)}
        env.update(
            OUTPUT_DIR=str(workspace.output_dir.resolve()),
            MPLBACKEND="Agg",
            PYTHONIOENCODING="utf-8",
            **self.tool_env(workspace),
        )
        proc = subprocess.Popen(
            [self.python, str(code_path.resolve())],
            cwd=workspace.output_dir,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=env,
        )
        self._procs[workspace.run_id] = proc
        try:
            return await asyncio.to_thread(self._communicate, proc, timeout)
        finally:
            # Cancelled (Stop) or hit the timeout guard → the process is still running → kill it now
            if proc.poll() is None:
                proc.kill()
            self._procs.pop(workspace.run_id, None)

    @staticmethod
    def _communicate(proc: subprocess.Popen, timeout: int) -> RawRun:
        try:
            out, err = proc.communicate(timeout=timeout)
            return RawRun(proc.returncode, decode_output(out), decode_output(err))
        except subprocess.TimeoutExpired:
            proc.kill()
            out, err = proc.communicate()
            return RawRun(124, decode_output(out), decode_output(err), timed_out=True)

    async def _kill(self, workspace) -> None:
        proc = self._procs.get(workspace.run_id)
        if proc and proc.poll() is None:
            proc.kill()
